4.  **`main.c` (or a new `game_logic.c`):**
    - The core logic for `check_and_grant_daily_bonus` should look something like this:
    ```c
    #include <time.h>

    // (Assume analytics_track_event and ui_display_bonus_message are declared)
    void check_and_grant_daily_bonus(PlayerState* player) {
        time_t now = time(NULL);
        struct tm* last_claim_date = gmtime(&player->last_bonus_claim_timestamp);
        struct tm* current_date = gmtime(&now);

        // Robustness Check: Compare calendar date, not just timestamp.
        // This prevents re-claiming by setting the clock backwards on the same day.
        bool is_new_day = (current_date->tm_year > last_claim_date->tm_year) || 
                          (current_date->tm_year == last_claim_date->tm_year && current_date->tm_yday > last_claim_date->tm_yday);

        if (is_new_day) {
            player->coins += 100;
            player->last_bonus_claim_timestamp = now;

            // Call UI and Analytics
            ui_display_bonus_message(100);
            analytics_track_event("daily_bonus_claimed", 100);

            // CRITICAL: Save state immediately to prevent re-awarding on next launch
            save_game_state(player);
        }
    }
    ```
